impl Solution {
    pub fn max_students(seats: Vec<Vec<char>>) -> i32 {
        let m = seats.len();
        let n = seats[0].len();

        // For each row, create a bitmask of available seats ('.')
        let mut avail = vec![0; m];
        for i in 0..m {
            let mut mask = 0;
            for j in 0..n {
                if seats[i][j] == '.' {
                    mask |= 1 << j;
                }
            }
            avail[i] = mask;
        }

        // Precompute all valid seatings for a single row:
        // A seating is valid if:
        // 1) It only uses available seats
        // 2) No two students sit next to each other (no cheating left/right)
        // We'll store all valid seatings for each row in a vector.
        let mut valid_rows = vec![Vec::new(); m];
        for i in 0..m {
            let limit = 1 << n;
            for state in 0..limit {
                // state must be subset of avail[i]
                if (state & avail[i]) == state && (state & (state >> 1)) == 0 {
                    valid_rows[i].push(state);
                }
            }
        }

        // DP:
        // dp[row][state] = max number of students seated up to row with this row's seating = state
        // Transition:
        // For each valid state in row i,
        // for each valid state in row i-1,
        // check no cheating diagonally:
        // no student in state at j can peek at student in prev_state at j-1 or j+1
        // i.e. (state & (prev_state << 1)) == 0 and (state & (prev_state >> 1)) == 0

        let mut dp = vec![std::collections::HashMap::new(); m];
        // Initialize dp for first row
        for &state in &valid_rows[0] {
            dp[0].insert(state, state.count_ones() as i32);
        }

        for i in 1..m {
            for &state in &valid_rows[i] {
                let count = state.count_ones() as i32;
                for (&prev_state, &prev_count) in dp[i - 1].iter() {
                    if (state & (prev_state << 1)) == 0 && (state & (prev_state >> 1)) == 0 {
                        let entry = dp[i].entry(state).or_insert(0);
                        *entry = (*entry).max(prev_count + count);
                    }
                }
            }
        }

        // The answer is the max value in dp[m-1]
        if m == 1 {
            // If only one row, just max count in dp[0]
            dp[0].values().copied().max().unwrap_or(0)
        } else {
            dp[m - 1].values().copied().max().unwrap_or(0)
        }
    }
}

